mapper.select:
SELECT * FROM external_workitem_link
WHERE tenant_id = #{tenantId} AND binding_id = #{bindingId}
  AND external_workitem_id = #{externalWorkitemId}
LIMIT 1

SELECT * FROM external_workitem_link
WHERE tenant_id = #{tenantId} AND provider = #{provider} AND workitem_id = #{workitemId}
LIMIT 1

SELECT * FROM external_workitem_link
WHERE tenant_id = #{tenantId} AND workitem_id = #{workitemId}
ORDER BY gmt_create ASC, id ASC

SELECT * FROM external_workitem_link

    tenant_id = #{tenantId}
    AND provider = #{provider}
    AND external_workitem_id = #{externalWorkitemId}

ORDER BY gmt_create DESC, id DESC
LIMIT #{offset}, #{limit}

SELECT * FROM external_workitem_link
WHERE binding_id = #{bindingId} AND id > #{afterId}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE external_workitem_link
SET remote_version_hash = #{remoteVersionHash}, last_sync_direction = #{lastSyncDirection}
WHERE id = #{id}

UPDATE external_workitem_link
SET sync_status = #{syncStatus},
    last_error_code = #{lastErrorCode},
    last_error = #{lastError}
WHERE id = #{id}
